        return;
    end
    local EventFuncs=self.Events[EventType];
    if EventFuncs ~=nil then
        for i, FuncData in pairs(EventFuncs) do
            if FuncData.Func==Func and FuncData.Object==Object then
                EventFuncs[i]=nil;
